  #root = new Node();

  /** @type {number} */
  #size = 0;

  /** @type {number} */
  #nodeCount = 1;

  /**
   * @param {unknown} word Candidate word.
   */
  #checkWord(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
  }

  /**
   * @param {unknown} prefix Candidate prefix.
   */
  #checkPrefix(prefix) {
    if (typeof prefix !== 'string') throw new TypeError('prefix must be a string');
  }

  /**
   * @param {unknown} text Candidate text.
   */
  #checkText(text) {
    if (typeof text !== 'string') throw new TypeError('text must be a string');
  }

  /**
   * @param {unknown} limit Candidate limit.
   */
  #checkLimit(limit) {
    if (limit === Number.POSITIVE_INFINITY) return;
    if (!Number.isSafeInteger(limit) || limit < 0) {
      throw new TypeError('limit must be a non-negative integer');
    }
  }

  /**
   * Walks to the node for a string, without creating anything.
   * @param {string} str String to walk.
   * @returns {Node | null} Node at that string, or null when absent.
   */
  #walk(str) {
    let node = this.#root;
    for (const ch of codePoints(str)) {
      const child = node.children.get(ch);
      if (!child) return null;
      node = child;
    }
    return node;
  }

  /**
   * Collects [word, value] pairs under a node in code point order.
   * @param {Node} node Node to start from.
   * @param {string} prefixStr Word represented by that node.
   * @param {Array<[string, unknown]>} out Accumulator.
   * @param {number} limit Maximum number of entries to collect.
   */
  #collect(node, prefixStr, out, limit) {
    if (out.length >= limit) return;
    if (node.hasValue) {
      out.push([prefixStr, node.value]);
      if (out.length >= limit) return;
    }
    for (const ch of sortedKeys(node.children)) {
      this.#collect(node.children.get(ch), prefixStr + ch, out, limit);
      if (out.length >= limit) return;
    }
  }

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    this.#checkWord(word);
    const chars = codePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const ch of chars) {
      let child = node.children.get(ch);
      if (!child) {
        child = new Node();
        node.children.set(ch, child);
        this.#nodeCount += 1;
      }
      node = child;
      path.push(node);
    }
    const isNew = !node.hasValue;
    const previous = node.value;
    node.hasValue = true;
    node.value = value;
    if (isNew) {
      for (const n of path) n.count += 1;
      this.#size += 1;
      return undefined;
    }
    return previous;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    this.#checkWord(word);
    const node = this.#walk(word);
    return node && node.hasValue ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    this.#checkWord(word);
    const node = this.#walk(word);
    return Boolean(node && node.hasValue);
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    this.#checkWord(word);
    const chars = codePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const ch of chars) {
      const child = node.children.get(ch);
      if (!child) return false;
      node = child;
      path.push(node);
    }
    if (!node.hasValue) return false;
    node.hasValue = false;
    node.value = undefined;
    for (const n of path) n.count -= 1;
    this.#size -= 1;
    for (let i = path.length - 1; i > 0; i -= 1) {
      const current = path[i];
      if (current.count === 0 && current.children.size === 0) {
        const parent = path[i - 1];
        parent.children.delete(chars[i - 1]);
        this.#nodeCount -= 1;
      } else {
        break;
      }
    }
    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    this.#checkPrefix(prefix);
    const node = this.#walk(prefix);
    return node ? node.count : 0;
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    this.#checkPrefix(prefix);
    this.#checkLimit(limit);
    const node = this.#walk(prefix);
    if (!node) return [];
    const out = [];
    this.#collect(node, prefix, out, limit);
    return out.map(([word]) => word);
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const out = [];
    this.#collect(this.#root, '', out, Number.POSITIVE_INFINITY);
    return out;
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    this.#checkText(text);
    let node = this.#root;
    let best = node.hasValue ? { word: '', value: node.value } : null;
    let current = '';
    for (const ch of codePoints(text)) {
      const child = node.children.get(ch);
      if (!child) break;
      current += ch;
      node = child;
      if (node.hasValue) best = { word: current, value: node.value };
    }
    return best;
  }
}
